GRAPH = {"a": ["b", "c"], "b": ["d"], "c": ["d", "e"], "d": [], "e": ["f"], "f": []}
def discover(node, depth, seen):
    if depth < 0 or node in seen: return
    seen.add(node)
    print("  " * (2 - depth) + node)
    for nxt in GRAPH[node]:
        discover(nxt, depth - 1, seen)
print("budget=2:"); discover("a", 2, set())

